class Solution {
  public int[] makeParityAlternating(int[] nums) {
    int n = nums.length;
    if (n == 1) return new int[] {0, 0};
    int[] cost = new int[2];
    for (int i = 0; i < n; i++) {
      int parity = Math.floorMod(nums[i], 2);
      for (int pattern = 0; pattern < 2; pattern++)
        if (parity != (i + pattern) % 2) cost[pattern]++;
    }
    int min = Math.min(cost[0], cost[1]);
    long bestRange = Long.MAX_VALUE;
    for (int pattern = 0; pattern < 2; pattern++) {
      if (cost[pattern] != min) continue;
      long fixedMin = Long.MAX_VALUE, fixedMax = Long.MIN_VALUE;
      List<Long> wrong = new ArrayList<>();
      for (int i = 0; i < n; i++) {
        if (Math.floorMod(nums[i], 2) == (i + pattern) % 2) {
          fixedMin = Math.min(fixedMin, nums[i]);
          fixedMax = Math.max(fixedMax, nums[i]);
        } else wrong.add((long) nums[i]);
      }
      java.util.Collections.sort(wrong);
      int w = wrong.size();
      if (w == 0) {
        bestRange = Math.min(bestRange, fixedMax - fixedMin);
        continue;
      }
      long limit = Math.min(fixedMin, wrong.get(0) + 1);
      java.util.TreeSet<Long> candidates = new java.util.TreeSet<>();
      for (long v : wrong) {
        candidates.add(v - 1);
        candidates.add(v + 1);
      }
      if (fixedMin != Long.MAX_VALUE) candidates.add(fixedMin);
      for (long lo : candidates) {
        if (lo > limit) break;
        // elements with v - 1 >= lo choose v - 1; others choose v + 1
        int idx = 0;
        while (idx < w && wrong.get(idx) - 1 < lo) idx++;
        long maxVal = fixedMax;
        if (idx > 0) maxVal = Math.max(maxVal, wrong.get(idx - 1) + 1);
        if (idx < w) maxVal = Math.max(maxVal, wrong.get(w - 1) - 1);
        long minVal = lo;
        bestRange = Math.min(bestRange, maxVal - minVal);
      }
    }
    return new int[] {min, (int) bestRange};
  }
}
